	if userSource == idp.getName(): idpType = idp.getType()
return idpType

onChange.script:

if origin == 'Browser':
	enable = (self.props.selected or False)
	retVal, msg = system.kanoa.security.updateUserField(self.view.custom.values.userId, 'gatewayAdmin', enable, self.view.custom.security.userId)

	if msg: system.perspective.sendMessage("showFailerToast", "User not updated: %s"%msg)
	else: 
		system.perspective.sendMessage("showSuccessfulToast", "User updated")

	system.perspective.sendMessage('updateUsers')		

return

