customMethods.script:

userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)
userInfo = dict(self.view.custom.values)
if self.view.custom.values['userId']: 
	system.perspective.print("userInfo: %s, userId: %s"%(userInfo, userId))
	retVal, msg = system.kanoa.security.updateUser(userInfo, userId)
	if msg: system.perspective.sendMessage("showFailerToast", "User not updated: %s"%msg)
	else: system.perspective.sendMessage("showSuccessfulToast", "User updated")
	self.view.refreshBinding("custom.values")
else:
	system.kanoa.security.addUserToUserSource(userInfo)
	userId, msg = system.kanoa.security.addUser(userInfo, userId)
	if msg: system.perspective.sendMessage("showFailerToast", "User not created: %s"%msg)
	else: 
		system.perspective.sendMessage("showSuccessfulToast", "User created")
		self.view.params.values.userId = userId

system.perspective.sendMessage('updateUsers')

return
